window.kbPageData["views/entry/k-3e95b77eeabd0099"] = {"key":"entry/k-3e95b77eeabd0099","state":{"route":"entry/k-3e95b77eeabd0099"},"node":{"id":"k-3e95b77eeabd0099","mode":"k","title":"高标准农田","type":"概念与词义","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["高标准农田建设"],"qs":["国考 2024 副省级 申论#4","国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["rural"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["公共管理"],"来源主题":["农业与城乡治理"],"资料类别":["非时政"]},"directorySummary":"高标准农田是通过田块整治、灌排设施建设和耕地质量提升等措施建成的集中连片、旱涝保收、高产稳产的农田。","review":{"title":"高标准农田","type":"概念与词义","definition":"高标准农田是通过田块整治、灌排设施建设和耕地质量提升等措施建成的集中连片、旱涝保收、高产稳产的农田。","explanation":"田块整治便于连片耕作，灌排设施提高农田抗旱排涝能力，建后管护有助于维持设施和耕地的生产能力。2023年12月中央农村工作会议提出，加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2024 副省级 申论#4":"从资料4提取高标准农田建设的实际成效，按项目管理环节归纳问题并使改进建议与问题一一对应。","国考 2025 副省级 行测#6":"对照粮食安全部署，区分高标准农田建设与建成后的管护，核对它们各自涉及的耕地保障要求。"}},"aspects":[{"title":"建设成效与项目管理","uses":[{"unit":"Q1","role":"直接考查","use":"本题 要求汇报C市调研结果并提出改进建议。材料以灌排改善、土地整合和特色产业发展说明成效，并以规划地块与实地不符、验收不严、田间道不合规和有机肥以发代施说明项目管理问题。","evidence":"通过高标准农田改造，亩均效益增加了200多元。","qids":["国考 2024 副省级 申论#4"]}]},{"title":"粮食安全中的建设投入与管护","uses":[{"unit":"Q2","role":"直接考查","use":"本题 均要求清点正确的粮食安全举措。③符合2023年12月中央农村工作会议关于高标准农田建设投入、管护和耕地数量质量保障的部署。①②③⑤共四项正确，三卷均选C。","evidence":"加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升","qids":["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]}]}],"sources":[{"id":"18b15dd81bc52dab","label":"高标准农田建设","topic":"农业与城乡治理","category":"非时政","text":"5.高标准农田建设\n高标准农田是指通过土地整治、设施完善和生态优化形成的旱涝保收、高产稳产耕地，\n具有集中连片、土壤肥沃、抗灾能力强等特点，是国家粮食安全的核心保障。《逐步把永久\n基本农田建成高标准农田实施方案》提出到 2030 年，力争累计建成高标准农田 13.5 亿亩，\n累计改造提升 2.8 亿亩，统筹规划、同步实施高效节水灌溉，新增高效节水灌溉面积 8000\n万亩；到 2035 年，力争将具备条件的永久基本农田全部建成高标准农田，累计改造提升 4.55\n亿亩，新增高效节水灌溉面积 1.3 亿亩。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2024 副省级 申论#4":{"paper":"国考 2024 副省级 申论","n":4,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",3],"card":"e48d130ae52bf3e4ab82eca0","links":[{"id":"k-3e95b77eeabd0099","role":"直接考查","why":"材料明确了高标准农田建设的目标，汇报需结合灌溉条件和亩均效益的改善说明建设成效。"}]},"国考 2025 副省级 行测#6":{"paper":"国考 2025 副省级 行测","n":6,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",1],"asrc":["ff0b352b44d417525086.pdf",2],"card":"ff24cb98d02636b69cd754bf","links":[{"id":"k-3e95b77eeabd0099","role":"直接考查","why":"该部署将高标准农田投入和管护与耕地数量、质量保障相联系。"}]},"国考 2025 地市级 行测#6":{"paper":"国考 2025 地市级 行测","n":6,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",1],"asrc":["8cece062c7c079b53130.pdf",2],"card":"692576f7e1cbee543408917c","links":[{"id":"k-3e95b77eeabd0099","role":"直接考查","why":"题目核对农田建设和管护投入服务于耕地数量保障与质量提升的要求。"}]},"国考 2025 行政执法 行测#6":{"paper":"国考 2025 行政执法 行测","n":6,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",1],"asrc":["e2c4b1970d2b49eac0fd.pdf",2],"card":"712cd85b1fc69bc908b841c9","links":[{"id":"k-3e95b77eeabd0099","role":"直接考查","why":"该部署把建设投入和建后管护与耕地数量、质量保障相联系。"}]}},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-3e95b77eeabd0099":[["国考 2024 副省级 申论#4"],["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]]}};
